use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
use std::os::unix::process::ExitStatusExt;
use std::process::Command;

const REF: &str = "/workspace/dataset/test14_executable";

fn run(exe: &str, args: &[&[u8]]) -> (Option<i32>, Option<i32>, Vec<u8>, Vec<u8>) {
    let mut c = Command::new(exe);
    for a in args { c.arg(OsStr::from_bytes(a)); }
    let o = c.output().expect("spawn");
    (o.status.code(), o.status.signal(), o.stdout, o.stderr)
}

#[test]
fn observes_sigabrt_and_nonutf8() {
    if !std::path::Path::new(REF).exists() { eprintln!("SKIP"); return; }
    let (code, sig, out, err) = run(REF, &[b"--a"]);
    println!("missing argv2: code={:?} signal={:?} stdout={} stderr_len={}", code, sig, out.len(), err.len());
    assert_eq!(sig, Some(6));
    assert!(out.is_empty());
    println!("stderr={:?}", String::from_utf8_lossy(&err));
    let (code2, sig2, out2, err2) = run(REF, &[b"\xff", b"5"]);
    println!("nonutf8: code={:?} sig={:?} stdout={:?} err={}", code2, sig2, String::from_utf8_lossy(&out2), err2.len());
    assert_eq!(code2, Some(0));
    assert_eq!(out2, b"1 0\n");
}
EOF
